from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3.common.common import LocalBasicPage
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage


class UserAccountManagementForNemuadmin(object):

    def __init__(self, driver):
        self._user_account_management = UserAccountManagementPage(driver)

    @property
    def user_account_management(self):
        return self._user_account_management


class UserAccountManagementPage(NavigatablePage):
    _EXPAND_ACCOUNT_MANAGEMENT_DROPDOWN_MENU_XPATH = "//user-account-management"
    _OPEN_USER_ACCOUNT_MANAGEMENT_POPUP_XPATH = ('//user-account-management//button[contains(text(), '
                                                 '"User Account Management")]')

    def __init__(self, driver):
        super(UserAccountManagementPage, self).__init__(driver)
        self._driver = LocalBasicPage(driver)
        self._local_user_account_management_tab = LocalUserAccountManagementTab(driver)
        self._service_user_account_management_tab = ServiceAccountManagementTab(driver)

    def _get_route_list(self):
        pass

    def navigate_to(self, timeout=60):
        self._driver.click_enabled_element((By.XPATH, self._EXPAND_ACCOUNT_MANAGEMENT_DROPDOWN_MENU_XPATH), timeout)
        self._driver.click_enabled_element((By.XPATH, self._OPEN_USER_ACCOUNT_MANAGEMENT_POPUP_XPATH), timeout)

    def change_username_for_bts_system_administrator(self, username):
        return self._local_user_account_management_tab.change_username_for_bts_system_administrator(username)

    def change_password_for_bts_system_administrator(self, new_password, confirm_password):
        return self._local_user_account_management_tab.change_password_for_bts_system_administrator(new_password,
                                                                                                    confirm_password)

    def change_password_for_service_account(self, username, old_password, new_password, confirm_password):
        return self._service_user_account_management_tab.change_password_for_service_account(username,
                                                                                             old_password,
                                                                                             new_password,
                                                                                             confirm_password)

    def configure_local_user_account(self, account_type, username=None, alias=None,
                                     old_password=None, new_password=None, confirm_password=None,
                                     activate_state='Active', timeout=60):
        return self._local_user_account_management_tab.configure_local_user_account(account_type,
                                                                                    username,
                                                                                    alias,
                                                                                    old_password,
                                                                                    new_password,
                                                                                    confirm_password,
                                                                                    activate_state,
                                                                                    timeout)


class UserAccountManagementModal(LocalBasicPage):
    _USER_COUNT_VIEW_XPATH = '//user-account-management'
    _LOGOUT_BUTTON_XPATH = '//div[@class="user-account-view"]//ui-button[@a-text="Logout"]'
    _SWITCH_TO_LOCAL_USER_ACCOUNT_TAB_XPATH = "//*[text()='Local User Account Management']"
    _SWITCH_TO_SERVICE_ACCOUNT_TAB_XPATH = "//*[text()='Service Account Management']"
    _EXPAND_ACCOUNT_LIST_XPATH = "//uam-local-tab//wf-dropdown//button"

    def __init__(self, driver):
        super(UserAccountManagementModal, self).__init__(driver)

    def _switch_to_local_user_account_management_tab(self):
        self.click_enabled_element((By.XPATH, self._SWITCH_TO_LOCAL_USER_ACCOUNT_TAB_XPATH))

    def _switch_to_service_account_management_tab(self):
        self.click_enabled_element((By.XPATH, self._SWITCH_TO_SERVICE_ACCOUNT_TAB_XPATH))

    def _fill_empty_field(self, element_value, element_xpath):
        if element_value is not None:
            self.insert_text_to_enable_element((By.XPATH, element_xpath), element_value)

    def _click_enabled_button(self, button_xpath):
        self.click_enabled_element((By.XPATH, button_xpath))

    def _get_validation_status(self, validation_msg_xpath):
        """
        Gets status of password validation.

        :return: bool: True if validation succeeded, False otherwise
        """
        return self.check_if_element_has_text((By.XPATH, validation_msg_xpath), "Process completed.", 30)


class LocalUserAccountManagementTab(UserAccountManagementModal):
    _BTS_ACCOUNT_TYPE_BASE_XPATH = '//uam-local-tab//span[text()="{}"]'
    _BTS_SYSTEM_ADMINISTRATOR = 'BTS System Administrator'
    _BTS_SECURITY_ADMINISTRATOR = 'BTS Security Administrator'
    _BTS_APPLICATION_ADMINISTRATOR = 'BTS Application Administrator'
    _BTS_READ_ONLY_USER = 'BTS Read-Only User'
    _ACCOUNT_WITHOUT_USERNAME_LIST = [_BTS_SECURITY_ADMINISTRATOR,
                                      _BTS_APPLICATION_ADMINISTRATOR,
                                      _BTS_READ_ONLY_USER]

    _SELECT_BTS_SYSTEM_ADMINISTRATOR_ELEMENT_XPATH = "//uam-local-tab//wf-dropdown-item[1]//a"
    _SELECT_BTS_SECURITY_ADMINISTRATOR_ELEMENT_XPATH = "//uam-local-tab//wf-dropdown-item[2]//a"
    _SELECT_BTS_APPLICATION_ADMINISTRATOR_ELEMENT_XPATH = "//uam-local-tab//wf-dropdown-item[3]//a"
    _SELECT_BTS_READ_ONLY_USER_ELEMENT_XPATH = "//uam-local-tab//wf-dropdown-item[4]//a"

    _INPUT_USERNAME_XPATH = '//div[*[contains(text(), "User name")]]//input'
    _INPUT_ALIAS_XPATH = '//div[*[contains(text(), "Alias")]]//input'
    _INPUT_OLD_PASSWORD_XPATH = '//div[*[contains(text(), "Old password")]]//input'
    _INPUT_NEW_PASSWORD_XPATH = '//div[*[contains(text(), "New password")]]//input'
    _INPUT_CONFIRM_PASSWORD_XPATH = '//div[*[contains(text(), "Confirm password")]]//input'
    _CURRENT_ACCOUNT_STATE = '//div[*[contains(text(), "Account activate state")]]//span[@class="selected-label"]//span'
    _ACCOUNT_STATE_DROP_BUTTON = '//div[*[contains(text(), "Account activate state")]]//button'
    _ACCOUNT_STATE_DROP_ITEM = '//div[*[contains(text(), "Account activate state")]]//li[//span[text()="{}"]]'

    _SAVE_BUTTON_XPATH = '//uam-modal-footer//button[contains(text(), "Save")]'
    _CLOSE_BUTTON_XPATH = '//uam-modal-footer//button[contains(text(), "Close")]'
    _VALIDATION_MESSAGE_XPATH = '//uam-validation-message//*[contains(@class, "uam-validation-message")]'
    _VALIDATION_SUCCESS_MSG = 'Process completed'

    def __init__(self, driver):
        super(LocalUserAccountManagementTab, self).__init__(driver)

    def _select_account_type_from_local_user_accounts_list(self, account_type):
        self.click_enabled_element((By.XPATH, self._EXPAND_ACCOUNT_LIST_XPATH))
        self.click_enabled_element((By.XPATH, self._BTS_ACCOUNT_TYPE_BASE_XPATH.format(account_type)))

    def change_username_for_bts_system_administrator(self, username):
        self._switch_to_local_user_account_management_tab()
        self._select_account_type_from_local_user_accounts_list(self._BTS_SYSTEM_ADMINISTRATOR)
        self._fill_empty_field(username, self._INPUT_USERNAME_XPATH)
        self._click_enabled_button(self._SAVE_BUTTON_XPATH)
        validation_status = self._get_validation_status(self._VALIDATION_MESSAGE_XPATH)
        self._click_enabled_button(self._CLOSE_BUTTON_XPATH)
        self.disable_message_box()
        return validation_status

    def change_password_for_bts_system_administrator(self, new_password, confirm_password):
        self._switch_to_local_user_account_management_tab()
        self._select_account_type_from_local_user_accounts_list(self._BTS_SYSTEM_ADMINISTRATOR)
        self._fill_empty_field(new_password, self._INPUT_NEW_PASSWORD_XPATH)
        self._fill_empty_field(confirm_password, self._INPUT_CONFIRM_PASSWORD_XPATH)
        self._click_enabled_button(self._SAVE_BUTTON_XPATH)
        validation_status = self._get_validation_status(self._VALIDATION_MESSAGE_XPATH)
        self._click_enabled_button(self._CLOSE_BUTTON_XPATH)
        self.disable_message_box()
        return validation_status

    def _configure_local_user_account(self, username=None, alias=None,
                                      old_password=None, new_password=None, confirm_password=None,
                                      activate_state='Active', timeout=60):
        self._fill_empty_field(username, self._INPUT_USERNAME_XPATH)
        self._fill_empty_field(alias, self._INPUT_ALIAS_XPATH)
        self._fill_empty_field(old_password, self._INPUT_OLD_PASSWORD_XPATH)
        self._fill_empty_field(new_password, self._INPUT_NEW_PASSWORD_XPATH)
        self._fill_empty_field(confirm_password, self._INPUT_CONFIRM_PASSWORD_XPATH)

        if activate_state != self.get_text_by_xpath(self._CURRENT_ACCOUNT_STATE):
            self.select_element_from_dropdown_list_by_text_and_click(
                activate_state,
                (By.XPATH, self._ACCOUNT_STATE_DROP_BUTTON),
                (By.XPATH, self._ACCOUNT_STATE_DROP_ITEM.format(activate_state)))
        self._click_enabled_button(self._SAVE_BUTTON_XPATH)
        try:
            self.wait_for_text_present_in_element((By.XPATH, self._VALIDATION_MESSAGE_XPATH),
                                                  self._VALIDATION_SUCCESS_MSG,
                                                  timeout)
            status = True
        except TimeoutException:
            status = False
        self._click_enabled_button(self._CLOSE_BUTTON_XPATH)
        return status

    def configure_local_user_account(self, account_type, username=None, alias=None, old_password=None,
                                     new_password=None, confirm_password=None, activate_state='Active', timeout=60):
        self._switch_to_local_user_account_management_tab()
        self._select_account_type_from_local_user_accounts_list(account_type)
        if account_type == self._BTS_SYSTEM_ADMINISTRATOR and alias is not None:
            raise AttributeError('alias has to be None if "{}" is choosen'.format(self._BTS_SYSTEM_ADMINISTRATOR))
        if account_type in self._ACCOUNT_WITHOUT_USERNAME_LIST and username is not None:
            raise AttributeError('no need to configure username when account type is not {}'.format(
                self._BTS_SYSTEM_ADMINISTRATOR))
        return self._configure_local_user_account(username=username,
                                                  alias=alias,
                                                  old_password=old_password,
                                                  new_password=new_password,
                                                  confirm_password=confirm_password,
                                                  activate_state=activate_state,
                                                  timeout=timeout)


class ServiceAccountManagementTab(UserAccountManagementModal):
    _INPUT_USERNAME_XPATH = "//*[@id='uam-service-user-name']"
    _INPUT_OLD_PASSWORD_XPATH = "//*[@id='uam-service-old-password']"
    _INPUT_NEW_PASSWORD_XPATH = "//*[@id='uam-service-new-password']"
    _INPUT_CONFIRM_PASSWORD_XPATH = "//*[@id='uam-service-confirm-password']"

    _SAVE_BUTTON_XPATH = "//uam-modal-footer/ui-button[1]"
    _CLOSE_BUTTON_XPATH = "//uam-modal-footer/ui-button[2]"
    _VALIDATION_MESSAGE_XPATH = "//uam-validation-message/div/div/span"

    def __init__(self, driver):
        super(ServiceAccountManagementTab, self).__init__(driver)

    def change_password_for_service_account(self, username, old_password, new_password, confirm_password):
        self._switch_to_service_account_management_tab()
        self._fill_empty_field(username, self._INPUT_USERNAME_XPATH)
        self._fill_empty_field(old_password, self._INPUT_OLD_PASSWORD_XPATH)
        self._fill_empty_field(new_password, self._INPUT_NEW_PASSWORD_XPATH)
        self._fill_empty_field(confirm_password, self._INPUT_CONFIRM_PASSWORD_XPATH)
        self._click_enabled_button(self._SAVE_BUTTON_XPATH)
        validation_status = self._get_validation_status(self._VALIDATION_MESSAGE_XPATH)
        self._click_enabled_button(self._CLOSE_BUTTON_XPATH)
        self.disable_message_box()
        return validation_status
